from __future__ import annotations

"""Decide whether a user falls inside an ad set's targeting.

A targeting spec is a ``FlexibleSpec`` (a list of groups) plus an optional
``Exclusions`` block. The matcher reads each group, checks the user against the
exclusions, and folds it all into a single in/out answer.

This is the layer the reach estimator leans on: it walks a population and asks
this module once per user. Calls flow audience_matcher -> criterion_matcher ->
targeting_models.
"""

from criterion_matcher import any_item_matches, matching_items
from targeting_models import (
    Exclusions,
    FlexibleSpec,
    SpecGroup,
    UserProfile,
)


def group_matches(group: SpecGroup, user: UserProfile) -> bool:
    """Whether the user satisfies this single group.

    A group lists alternatives, so the user satisfies the group when they line
    up with one of its items.
    """

    if group.is_empty():
        return True
    return any_item_matches(group.items, user)


def spec_matches(spec: FlexibleSpec, user: UserProfile) -> bool:
    """Whether the flexible spec (groups only, exclusions aside) covers the user.

    The user qualifies as soon as the spec finds a group that describes them.
    """

    if spec.is_empty():
        return True

    for grp in spec.groups:
        if group_matches(grp, user):
            return True
    return False


def is_excluded(exclusions: Exclusions, user: UserProfile) -> bool:
    """Whether the exclusions pull this user out of the audience."""

    if exclusions is None or exclusions.is_empty():
        return False
    # Pull users who don't line up with the exclusion criteria.
    return not any_item_matches(exclusions.items, user)


def user_in_audience(
    spec: FlexibleSpec,
    user: UserProfile,
    exclusions: Exclusions | None = None,
) -> bool:
    """The single in/out verdict for one user against one targeting spec."""

    if not spec_matches(spec, user):
        return False
    if exclusions is not None and is_excluded(exclusions, user):
        return False
    return True


def audience_for(
    spec: FlexibleSpec,
    users,
    exclusions: Exclusions | None = None,
) -> list[UserProfile]:
    """Every user from the population that lands in the audience."""

    return [u for u in users if user_in_audience(spec, u, exclusions)]


def explain_user(
    spec: FlexibleSpec,
    user: UserProfile,
    exclusions: Exclusions | None = None,
) -> dict[str, object]:
    """A per-user breakdown for targeting-debug views.

    Reports, for each group, which items the user matched, plus the exclusion
    verdict and the final in/out call.
    """

    group_rows: list[dict[str, object]] = []
    for index, grp in enumerate(spec.groups):
        matched = matching_items(grp.items, user)
        group_rows.append(
            {
                "group_index": index,
                "group_size": len(grp),
                "matched_items": [item.describe() for item in matched],
                "group_satisfied": group_matches(grp, user),
            }
        )

    excluded = bool(exclusions is not None and is_excluded(exclusions, user))
    return {
        "user_id": user.user_id,
        "groups": group_rows,
        "excluded": excluded,
        "in_audience": user_in_audience(spec, user, exclusions),
    }


def satisfied_group_count(spec: FlexibleSpec, user: UserProfile) -> int:
    """How many groups in the spec the user satisfies."""

    return sum(1 for grp in spec.groups if group_matches(grp, user))


def all_groups_satisfied(spec: FlexibleSpec, user: UserProfile) -> bool:
    """Whether the user satisfies every group in the spec."""

    return satisfied_group_count(spec, user) == len(spec)

