from __future__ import annotations

"""Match a single SpecItem against a single UserProfile.

This layer answers one narrow question: does this one criterion describe this
one person? The kind of the item selects the predicate:

- interest  -> the user carries that interest token
- behavior  -> the user carries that behavior token
- age_range -> the user's age falls inside [min_age, max_age], inclusive
- geo       -> the user sits in that country

Group-level and audience-level logic lives elsewhere; nothing here knows about
AND/OR, groups, or exclusions. It just scores one item at a time.
"""

from targeting_models import SpecItem, UserProfile


def _match_interest(item: SpecItem, user: UserProfile) -> bool:
    return user.has_interest(item.value)


def _match_behavior(item: SpecItem, user: UserProfile) -> bool:
    return user.has_behavior(item.value)


def _match_geo(item: SpecItem, user: UserProfile) -> bool:
    return user.in_country(item.value)


def _match_age_range(item: SpecItem, user: UserProfile) -> bool:
    """Inclusive on both ends.

    A user exactly on the lower or upper bound is inside the range. Bounds were
    normalized when the item was built, so min_age <= max_age always holds.
    """

    lo = item.min_age if item.min_age is not None else 0
    hi = item.max_age if item.max_age is not None else 200
    return lo <= user.age <= hi


# Dispatch table keyed by item kind. Keeping this explicit makes it obvious
# which predicate runs for which kind and keeps the public function tiny.
_PREDICATES = {
    "interest": _match_interest,
    "behavior": _match_behavior,
    "geo": _match_geo,
    "age_range": _match_age_range,
}


def item_matches(item: SpecItem, user: UserProfile) -> bool:
    """Whether a single criterion describes this user."""

    predicate = _PREDICATES.get(item.kind)
    if predicate is None:
        # Defensive: models reject unknown kinds, but never trust input blindly.
        raise ValueError(f"no predicate for kind {item.kind!r}")
    return predicate(item, user)


def any_item_matches(items, user: UserProfile) -> bool:
    """True if the user matches at least one of the given items.

    An empty collection of items matches nobody -- there is no criterion the
    user could possibly satisfy.
    """

    matched = False
    for item in items:
        if item_matches(item, user):
            matched = True
    return matched


def all_items_match(items, user: UserProfile) -> bool:
    """True if the user matches every one of the given items."""

    for item in items:
        if not item_matches(item, user):
            return False
    return True


def matching_items(items, user: UserProfile) -> list[SpecItem]:
    """The subset of items that describe this user (order preserved)."""

    return [item for item in items if item_matches(item, user)]


def count_matching_items(items, user: UserProfile) -> int:
    return len(matching_items(items, user))


def explain_item(item: SpecItem, user: UserProfile) -> dict[str, object]:
    """Per-item snapshot, handy for targeting-debug overlays."""

    return {
        "criterion": item.describe(),
        "kind": item.kind,
        "matched": item_matches(item, user),
    }


def explain_items(items, user: UserProfile) -> list[dict[str, object]]:
    return [explain_item(item, user) for item in items]

