from __future__ import annotations

"""Estimate reach: how many people in a sample population a spec would target.

This sits on top of the audience matcher. Given a targeting spec and a list of
``UserProfile`` rows standing in for a sample of the population, it counts the
matches and rolls up a small report the campaign UI shows next to the ad set.

Chain: reach_estimator -> audience_matcher -> criterion_matcher -> models.
"""

from audience_matcher import audience_for, user_in_audience
from targeting_models import Exclusions, FlexibleSpec, UserProfile


def estimate_reach(
    spec: FlexibleSpec,
    population: list[UserProfile],
    exclusions: Exclusions | None = None,
) -> int:
    """Count the users in the sample population the spec would reach."""

    return sum(1 for u in population if user_in_audience(spec, u, exclusions))


def reached_user_ids(
    spec: FlexibleSpec,
    population: list[UserProfile],
    exclusions: Exclusions | None = None,
) -> list[str]:
    """The ids of the reached users, in population order."""

    return [u.user_id for u in audience_for(spec, population, exclusions)]


def reach_fraction(
    spec: FlexibleSpec,
    population: list[UserProfile],
    exclusions: Exclusions | None = None,
) -> float:
    """Share of the sample population the spec reaches, in [0, 1]."""

    if not population:
        return 0.0
    return estimate_reach(spec, population, exclusions) / len(population)


def reach_report(
    spec: FlexibleSpec,
    population: list[UserProfile],
    exclusions: Exclusions | None = None,
) -> dict[str, object]:
    """A compact reach summary for the campaign UI."""

    reached = reached_user_ids(spec, population, exclusions)
    total = len(population)
    return {
        "population_size": total,
        "reach": len(reached),
        "reach_fraction": (len(reached) / total) if total else 0.0,
        "reached_user_ids": reached,
        "group_count": len(spec),
        "has_exclusions": bool(exclusions is not None and not exclusions.is_empty()),
    }


def compare_specs(
    specs: dict[str, FlexibleSpec],
    population: list[UserProfile],
) -> dict[str, int]:
    """Reach for several candidate specs against the same population.

    Useful when an advertiser is weighing a broad spec against a tight one and
    wants the projected audience size for each before they commit budget.
    """

    return {
        name: estimate_reach(spec, population)
        for name, spec in specs.items()
    }


def narrowing_effect(
    spec: FlexibleSpec,
    population: list[UserProfile],
    exclusions: Exclusions,
) -> dict[str, int]:
    """How much the exclusion block trims an otherwise-matching audience."""

    without = estimate_reach(spec, population, None)
    with_excl = estimate_reach(spec, population, exclusions)
    return {
        "reach_without_exclusions": without,
        "reach_with_exclusions": with_excl,
        "removed_by_exclusions": without - with_excl,
    }

