from __future__ import annotations

"""Domain models for ad-set targeting.

An ad set targets people with a ``FlexibleSpec``: a list of ``SpecGroup``
objects. Each group holds a bunch of ``SpecItem`` criteria (an interest, a
behavior, an age band, a country, ...). Alongside the flexible spec an ad set
may carry an ``Exclusions`` block listing criteria that pull people back out of
the audience.

A ``UserProfile`` is one person we could show the ad to: the interests and
behaviors they carry, their age, and the country they sit in. Nothing here
decides whether a user is *in* an audience -- these are just the shapes the
matcher and the reach estimator read.
"""

from dataclasses import dataclass, field


def _clean_token(label: str, value: str) -> str:
    if value is None or not str(value).strip():
        raise ValueError(f"{label} is required")
    return str(value).strip().lower()


def _clean_token_set(values: list[str] | None) -> frozenset[str]:
    cleaned: set[str] = set()
    for value in values or []:
        if value is None:
            continue
        text = str(value).strip().lower()
        if text:
            cleaned.add(text)
    return frozenset(cleaned)


# The kinds of criteria a single targeting item can express. A SpecItem always
# carries exactly one of these so the matcher knows which predicate to run.
VALID_KINDS = ("interest", "behavior", "age_range", "geo")


@dataclass(frozen=True)
class SpecItem:
    """One targeting criterion.

    ``kind`` selects what the item matches:

    - ``"interest"``  -> ``value`` is an interest token the user must carry.
    - ``"behavior"``  -> ``value`` is a behavior token the user must carry.
    - ``"age_range"`` -> ``min_age``/``max_age`` bound the user's age inclusive.
    - ``"geo"``       -> ``value`` is a country code the user must sit in.
    """

    kind: str
    value: str | None = None
    min_age: int | None = None
    max_age: int | None = None

    def __post_init__(self) -> None:
        kind = _clean_token("kind", self.kind)
        if kind not in VALID_KINDS:
            raise ValueError(f"unknown kind: {self.kind!r}")
        object.__setattr__(self, "kind", kind)

        if kind in ("interest", "behavior", "geo"):
            object.__setattr__(self, "value", _clean_token("value", self.value))
        if kind == "age_range":
            lo = 0 if self.min_age is None else int(self.min_age)
            hi = 200 if self.max_age is None else int(self.max_age)
            if lo < 0 or hi < 0:
                raise ValueError("age bounds must be non-negative")
            if lo > hi:
                raise ValueError("min_age cannot exceed max_age")
            object.__setattr__(self, "min_age", lo)
            object.__setattr__(self, "max_age", hi)

    def describe(self) -> str:
        if self.kind == "age_range":
            return f"age_range[{self.min_age}-{self.max_age}]"
        return f"{self.kind}:{self.value}"


@dataclass(frozen=True)
class SpecGroup:
    """A bucket of SpecItems.

    Within one group the items express alternatives: the group is about a
    single dimension of who you want (say "sports interests" or "frequent
    travelers"), and any one of the listed items can stand in for the rest.
    """

    items: tuple[SpecItem, ...] = ()

    def __post_init__(self) -> None:
        object.__setattr__(self, "items", tuple(self.items))

    def is_empty(self) -> bool:
        return len(self.items) == 0

    def __iter__(self):
        return iter(self.items)

    def __len__(self) -> int:
        return len(self.items)


@dataclass(frozen=True)
class FlexibleSpec:
    """The ordered list of spec groups for an ad set."""

    groups: tuple[SpecGroup, ...] = ()

    def __post_init__(self) -> None:
        object.__setattr__(self, "groups", tuple(self.groups))

    def is_empty(self) -> bool:
        return len(self.groups) == 0

    def __iter__(self):
        return iter(self.groups)

    def __len__(self) -> int:
        return len(self.groups)


@dataclass(frozen=True)
class Exclusions:
    """Criteria that remove a user from the audience.

    Each list is a flat set of criteria; a user touched by any of them is out.
    """

    items: tuple[SpecItem, ...] = ()

    def __post_init__(self) -> None:
        object.__setattr__(self, "items", tuple(self.items))

    def is_empty(self) -> bool:
        return len(self.items) == 0

    def __iter__(self):
        return iter(self.items)

    def __len__(self) -> int:
        return len(self.items)


@dataclass(frozen=True)
class UserProfile:
    """A person we could reach.

    ``interests`` and ``behaviors`` are token sets; ``age`` is whole years;
    ``country`` is a country code. Tokens are normalized to lowercase so
    "Travel" and "travel" line up.
    """

    user_id: str
    interests: frozenset[str] = field(default_factory=frozenset)
    behaviors: frozenset[str] = field(default_factory=frozenset)
    age: int = 0
    country: str = ""

    def __post_init__(self) -> None:
        uid = _clean_token("user_id", self.user_id)
        object.__setattr__(self, "user_id", uid)
        object.__setattr__(self, "interests", _clean_token_set(list(self.interests)))
        object.__setattr__(self, "behaviors", _clean_token_set(list(self.behaviors)))
        if int(self.age) < 0:
            raise ValueError("age must be non-negative")
        object.__setattr__(self, "age", int(self.age))
        object.__setattr__(self, "country", str(self.country).strip().lower())

    def has_interest(self, token: str) -> bool:
        return str(token).strip().lower() in self.interests

    def has_behavior(self, token: str) -> bool:
        return str(token).strip().lower() in self.behaviors

    def in_country(self, code: str) -> bool:
        return str(code).strip().lower() == self.country


# ---- convenience constructors used by seed data and tests -------------------

def interest(token: str) -> SpecItem:
    return SpecItem(kind="interest", value=token)


def behavior(token: str) -> SpecItem:
    return SpecItem(kind="behavior", value=token)


def geo(country_code: str) -> SpecItem:
    return SpecItem(kind="geo", value=country_code)


def age_range(min_age: int, max_age: int) -> SpecItem:
    return SpecItem(kind="age_range", min_age=min_age, max_age=max_age)


def group(*items: SpecItem) -> SpecGroup:
    return SpecGroup(items=tuple(items))


def flexible_spec(*groups: SpecGroup) -> FlexibleSpec:
    return FlexibleSpec(groups=tuple(groups))


def exclusions(*items: SpecItem) -> Exclusions:
