from dataclasses import dataclass, field


def _clean_token(label: str, value: str) -> str:
    if value is None or not str(value).strip():
        raise ValueError(f"{label} is required")
    return str(value).strip().lower()


def _clean_token_set(values: list[str] | None) -> frozenset[str]:
    cleaned: set[str] = set()
    for value in values or []:
        if value is None:
            continue
        text = str(value).strip().lower()
        if text:
            cleaned.add(text)
    return frozenset(cleaned)


# The kinds of criteria a single targeting item can express. A SpecItem always
# carries exactly one of these so the matcher knows which predicate to run.
VALID_KINDS = ("interest", "behavior", "age_range", "geo")


@dataclass(frozen=True)
class SpecItem:
    """One targeting criterion.

    ``kind`` selects what the item matches:

    - ``"interest"``  -> ``value`` is an interest token the user must carry.
    - ``"behavior"``  -> ``value`` is a behavior token the user must carry.
    - ``"age_range"`` -> ``min_age``/``max_age`` bound the user's age inclusive.
    - ``"geo"``       -> ``value`` is a country code the user must sit in.
    """

    kind: str
    value: str | None = None
    min_age: int | None = None
    max_age: int | None = None

    def __post_init__(self) -> None:
        kind = _clean_token("kind", self.kind)
        if kind not in VALID_KINDS:
            raise ValueError(f"unknown kind: {self.kind!r}")
        object.__setattr__(self, "kind", kind)

        if kind in ("interest", "behavior", "geo"):
            object.__setattr__(self, "value", _clean_token("value", self.value))
        if kind == "age_range":
            lo = 0 if self.min_age is None else int(self.min_age)
            hi = 200 if self.max_age is None else int(self.max_age)
            if lo < 0 or hi < 0:
                raise ValueError("age bounds must be non-negative")
            if lo > hi:
                raise ValueError("min_age cannot exceed max_age")
